import { siteURL } from './site-paths.js';
import { renderAtlasScroll, setupAtlasScroll, renderAtlasCompose, setupAtlasCompose } from './atlas-scroll.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const PALETTES=[{name:'A · Warmer accents',colors:[['Zhu Sha','#8B1A1A'],['Teng Huang','#E8A50F'],['Shi Lü','#4D8A63'],['Tian Qing','#6E9CB3'],['Qian Bai','#F2ECDE']]},{name:'B · Blue-led direction',colors:[['Tian Qing','#6E9CB3'],['Yue Bai','#CFE0E8'],['Yan Zhi','#9D2933'],['Dai','#4A4266'],['Qian Bai','#F2ECDE']]}];
// Dialogue and palette values transcribed from the author's original Color Agent concept.
const DIALOGUE=[
 {user:'I’m unsure how to color this palace magnet.',agent:'What feeling should the design convey?'},
 {prompt:'Which era and place should guide the palette?',user:'Qing-era Beijing, with a calm, contemporary feel.',agent:null},
 {agent:'For that brief: a warmer direction, or a softer blue-led palette.',palettes:true},
 {agent:'B pairs sky-inspired Tian Qing with moonlight-inspired Yue Bai.',source:'Tian Qing: Guide to the Study of Antiquities. Check period notes and source uncertainty.'},
 {agent:'Now preview both palettes across the whole drawing.',art:true},
 {user:'I prefer B. Soften the flowers and keep the blue sky.',agent:'I’ll adjust only the flowers. Review or accept when ready.',actions:true}
];
const paletteMarkup=()=>`<div class="color-chat-palettes">${PALETTES.map(p=>`<div><strong>${p.name}</strong><div class="color-chat-swatches">${p.colors.map(([name,hex])=>`<span style="--swatch:${hex}" title="${name} · ${hex}"><i></i><small>${name}</small></span>`).join('')}</div></div>`).join('')}</div>`;
function agentNote(step,i){return `<div class="color-agent-row-note" data-agent-note="${i}"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(step.title||'')}</h3><p>${esc(step.body||'')}</p></div></div>`;}
function phaseMarkup(d,i,step={}){return `<div class="color-chat-phase" data-phase="${i}" data-mobile-title="${String(i+1).padStart(2,'0')} · ${esc(step.title||'')}"><div class="color-agent-row-dialogue">${d.prompt?`<p class="color-chat-context">${esc(d.prompt)}</p>`:''}${d.user?`<div class="color-chat-message color-chat-user"><span class="color-message-label">Designer</span><p class="color-typed-message" data-message="${esc(d.user)}"><span class="color-message-reserve" aria-hidden="true">${esc(d.user)}</span><span data-typed-output>${esc(d.user)}</span></p></div>`:''}${d.agent?`<div class="color-chat-message color-chat-agent"><span class="color-message-label">Color Agent</span><p>${esc(d.agent)}</p>${d.palettes?paletteMarkup():''}${d.source?`<div class="color-chat-source"><span>Color record</span><strong>Tian Qing · 天青</strong><p>${esc(d.source)}</p></div>`:''}${d.art?`<div class="color-chat-art-pair">${['a','b'].map((key,j)=>`<figure class="color-chat-art"><img src="${siteURL('/assets/design-followup/color-agent-palace-'+key+'.jpg')}" alt="Original palace magnet study artwork, ${j?'cooler':'warmer'} direction" width="1620" height="1080"><figcaption>${j?'B · Cooler':'A · Warmer'}</figcaption></figure>`).join('')}</div><p class="color-chat-art-label">Roof · Sky · Flowers · Stone</p>`:''}${d.actions?'<div class="color-chat-actions"><span>Refine B</span><span>Accept direction</span></div>':''}</div>`:''}</div><p class="color-agent-mobile-note">${esc(step.body||'')}</p></div>`;}
export function renderColorAgent(source){const steps=source?.steps||[];return `<div class="color-agent-scroll color-agent-rows color-agent-separated" data-color-agent><div class="color-agent-stage"><div class="color-agent-heading"><span>Color Agent / Future concept</span><p>Design demonstration · scripted responses · no live AI</p></div><div class="color-agent-two-columns"><div class="color-agent-explanations">${DIALOGUE.map((_,i)=>agentNote(steps[i],i)).join('')}</div><div class="color-chat-window"><div class="color-chat-top"><span class="color-chat-symbol" aria-hidden="true">✳</span><span>Color Agent</span><span class="color-chat-step">01 / 06</span></div><div class="color-chat-content">${DIALOGUE.map((d,i)=>phaseMarkup(d,i,steps[i])).join('')}</div></div></div><p class="color-agent-footnote">Concept preview uses original study artwork; historical fit remains open to verification.</p></div></div>`;}
function atlasFigure(f){return `<figure class="color-atlas-figure color-vertical-figure"><img src="${siteURL(f.src)}" alt="${esc(f.alt||f.caption||'Original Color Atlas artwork')}" width="${f.width||1200}" height="${f.height||800}" loading="lazy" decoding="async">${f.caption?`<figcaption>${esc(f.caption).replaceAll('usual workflow','<span class="color-keep-phrase">usual workflow</span>').replaceAll('with the atlas','<span class="color-keep-phrase">with the atlas</span>')}</figcaption>`:''}</figure>`;}
export function renderColorAtlas(chapters){return `<div class="color-atlas-chapters">${chapters.map(c=>`<article class="color-atlas-subchapter color-atlas-${c.id}" id="atlas-${c.id}"><div class="color-atlas-copy"><h3>${esc(c.title)}</h3><ul>${(Array.isArray(c.body)?c.body:[c.body]).filter(Boolean).map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>${c.id==='connections'?renderAtlasScroll():c.id==='brief'?renderAtlasCompose():`<div class="color-atlas-media">${c.id==='artworks'?Array.from({length:Math.ceil(c.figures.length/2)},(_,j)=>`<div class="color-artwork-pair">${c.figures.slice(j*2,j*2+2).map(atlasFigure).join('')}</div>`).join(''):c.figures.map(atlasFigure).join('')}</div>`}</article>`).join('')}</div>`;}
function setupAbstract(root,p){const section=root.querySelector('#abstract');if(!section)return;section.classList.add('color-abstract-overview');section.querySelectorAll('.color-abstract-visual,.section-visuals').forEach(e=>e.remove());const body=section.querySelector('.section-body');body?.querySelector('.insights')?.remove();const items=p.sections.find(s=>s.id==='abstract')?.items||[];const assets=[['/assets/colorgene-02-system-404f4e0a.webp',3840,951],['/website-assets/atlas-display.svg',470,401],['/assets/design-followup/color-agent-base.svg',1960,1390]];const wrap=document.createElement('div');wrap.className='color-version-overview';wrap.innerHTML=items.map((item,i)=>`<article><div class="color-version-image"><img src="${siteURL(assets[i][0])}" width="${assets[i][1]}" height="${assets[i][2]}" alt="${esc(item.title)} original interface overview" loading="lazy"></div><span class="color-version-number">${esc(item.version||`Version ${i+1}.0`)} <span aria-hidden="true">·</span> ${esc(item.status||['CHI Poster 2026','In progress','Future'][i])}</span><h3>${esc(item.title)}</h3><p>${esc(item.body)}</p></article>`).join('');section.append(wrap);}
function setupPilot(root){const section=root.querySelector('#pilot');if(!section)return;section.classList.remove('with-visual','wide-visual','editorial-pair');section.classList.add('color-pilot-compact');const body=section.querySelector('.section-body'),visuals=section.querySelector('.section-visuals'),next=body?.querySelector('.insights');if(next){next.className='color-pilot-next';next.innerHTML='<h3>Next iteration</h3><ul><li>Fuller historical sources</li><li>Palettes tailored to each designer’s brief</li></ul>';section.append(next);}const firstFigure=visuals?.querySelector('.project-figure:not(.data-visual)'),quote=body?.querySelector('blockquote');if(firstFigure&&quote){const context=document.createElement('div');context.className='color-pilot-evidence-copy';visuals.prepend(context);context.append(firstFigure,quote);}const dv=visuals?.querySelector('[data-native-visual]');if(dv){dv.querySelector('.dv-title').textContent='Five designers in each group';const description=dv.querySelector('.dv-description');if(description)description.textContent='Questionnaire change and task completion';const title=dv.querySelector('.dv-panel-title');if(title)title.textContent='Questionnaire score change';} }
export function setupColorInteractions(root=document,p){
 if(p?.id!=='traditional-color')return()=>{};
 setupAbstract(root,p);setupPilot(root);
 const atlas=root.querySelector('#atlas'),atlasData=p.sections.find(s=>s.id==='atlas');
 if(atlas&&atlasData?.colorAtlasChapters){atlas.className='case-section color-atlas-complete';atlas.querySelector('.section-body')?.remove();atlas.querySelector('.section-visuals')?.remove();atlas.insertAdjacentHTML('beforeend',renderColorAtlas(atlasData.colorAtlasChapters));}
 const atlasScrollCleanup=setupAtlasScroll(atlas);
 const atlasComposeCleanup=setupAtlasCompose(atlas);
 const verticalSections=['research','colorgene','sources','compose'].map(id=>root.querySelector('#'+id)).filter(Boolean);
 verticalSections.forEach(section=>{section.classList.add('color-vertical-chapter');section.querySelectorAll('.project-figure').forEach((fig,i)=>{fig.classList.remove('reveal','motion-ready');fig.classList.add('color-vertical-figure');fig.style.setProperty('--figure-order',i);});});
 const verticalFigures=[...verticalSections.flatMap(section=>[...section.querySelectorAll('.color-vertical-figure')]),...root.querySelectorAll('.color-atlas-figure')];
 const future=p.sections.find(s=>s.id==='future'),source=future?.figures?.find(f=>f.layeredSource)?.layeredSource;
 const target=root.querySelector('#future .layered-source');if(source&&target){const holder=document.createElement('div');holder.innerHTML=renderColorAgent(source);target.replaceWith(holder.firstElementChild);root.querySelector('#future .section-visuals')?.classList.add('color-agent-visuals');}
 const agent=root.querySelector('[data-color-agent]');const artPairs=[...root.querySelectorAll('#outcomes .figure-pair,.color-atlas-artworks .color-artwork-pair')];artPairs.forEach(pair=>{pair.classList.add('color-artwork-pair');pair.querySelectorAll('figcaption').forEach(c=>{c.innerHTML=c.innerHTML.replaceAll('usual workflow','<span class="color-keep-phrase">usual workflow</span>').replaceAll('with the atlas','<span class="color-keep-phrase">with the atlas</span>');});});
 const insights=[...root.querySelectorAll('#research .insight')];insights.forEach((el,i)=>{el.classList.add('color-research-insight');el.style.setProperty('--insight-index',i)});
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),compact=matchMedia('(max-width:999px)');let frame=0,currentPhase=0;
 const readMode=()=>reduced.matches||compact.matches;
 function update(){
  frame=0;const vh=innerHeight,plain=readMode();
  for(const fig of verticalFigures){const r=fig.getBoundingClientRect(),pr=reduced.matches?1:clamp((vh*.94-r.top)/(vh*.26));fig.style.setProperty('--figure-reveal',pr.toFixed(3));}
  for(const el of insights){const r=el.getBoundingClientRect(),pr=reduced.matches?1:clamp((vh*.90-r.top)/(vh*.26));el.style.setProperty('--insight-progress',pr.toFixed(3));}
  for(const pair of artPairs){const r=pair.getBoundingClientRect(),distance=Math.abs(r.top+r.height/2-vh*.5)/(vh*.65+r.height*.25),focus=clamp(1-distance);pair.style.setProperty('--art-focus',reduced.matches?1:focus.toFixed(3));}
  if(agent){agent.classList.toggle('color-agent-read-mode',reduced.matches);const rows=[...agent.querySelectorAll('[data-phase]')];currentPhase=0;
   rows.forEach((el,i)=>{const rect=el.getBoundingClientRect(),local=reduced.matches?1:clamp((vh*.92-rect.top)/Math.min(vh*.53,Math.max(160,rect.height*.95)));if(local>.02)currentPhase=i;el.hidden=false;el.classList.toggle('is-phase-current',local>0&&local<1);el.classList.toggle('is-phase-filled',local>=.98);el.style.setProperty('--step-progress',local>0?1:0);const note=agent.querySelector(`[data-agent-note="${i}"]`);if(note)note.classList.toggle('is-note-visible',reduced.matches||local>.06);const typing=el.querySelector('[data-message]'),d=DIALOGUE[i];if(typing){const t=typing.dataset.message;typing.querySelector('[data-typed-output]').textContent=t.slice(0,Math.ceil(t.length*clamp(local/.48)));typing.classList.toggle('is-typing',!reduced.matches&&local>0&&local<.48)}const answer=el.querySelector('.color-chat-agent');const reveal=reduced.matches?1:d.user?clamp((local-.47)/.20):clamp(local/.35);if(answer){answer.style.setProperty('--reply-progress',reveal.toFixed(3));answer.classList.toggle('is-answer-visible',reveal>.5);}});
   agent.querySelector('.color-chat-step').textContent=`${String(currentPhase+1).padStart(2,'0')} / 06`;
  }
 }
 const queue=()=>{if(!frame)frame=requestAnimationFrame(update)};
 function measureAgent(){if(!agent)return;const small=innerWidth<=700;agent.querySelectorAll('[data-phase]').forEach((row,i)=>{const note=agent.querySelector(`[data-agent-note="${i}"]`);row.style.removeProperty('min-height');note?.style.removeProperty('min-height');if(!small&&note){const height=Math.ceil(Math.max(row.getBoundingClientRect().height,note.getBoundingClientRect().height));row.style.minHeight=height+'px';note.style.minHeight=height+'px';}});queue();}
 const agentObserver=agent?new ResizeObserver(()=>{if(!measurePending)measurePending=requestAnimationFrame(()=>{measurePending=0;measureAgent()})}):null;let measurePending=0;
 if(agentObserver)agentObserver.observe(agent.querySelector('.color-agent-two-columns'));
 requestAnimationFrame(measureAgent);
 function navigation(event){

  if(agent&&event.target.closest('[data-agent-next],[data-agent-prev]')){const direction=event.target.closest('[data-agent-next]')?1:-1,next=clamp(currentPhase+direction,0,5),travel=agent.offsetHeight-agent.querySelector('.color-agent-stage').offsetHeight;window.scrollTo({top:scrollY+agent.getBoundingClientRect().top-100+(next+.6)/6*travel,behavior:reduced.matches?'instant':'smooth'});}
 }
 root.addEventListener('click',navigation);window.addEventListener('scroll',queue,{passive:true});window.addEventListener('resize',queue,{passive:true});reduced.addEventListener('change',queue);compact.addEventListener('change',queue);update();
 return()=>{atlasScrollCleanup();atlasComposeCleanup();cancelAnimationFrame(frame);cancelAnimationFrame(measurePending);agentObserver?.disconnect();root.removeEventListener('click',navigation);window.removeEventListener('scroll',queue);window.removeEventListener('resize',queue);reduced.removeEventListener('change',queue);compact.removeEventListener('change',queue)};
}
